CREATE TABLE IF NOT EXISTS beta_users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, email TEXT, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('tester','admin')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS beta_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES beta_users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT NOT NULL, last_seen_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS beta_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, pack_key TEXT NOT NULL, task_key TEXT NOT NULL UNIQUE, title TEXT NOT NULL, instructions TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, required INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS beta_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES beta_users(id) ON DELETE CASCADE, pack_key TEXT NOT NULL, title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS beta_responses (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES beta_users(id) ON DELETE CASCADE, task_id INTEGER NOT NULL REFERENCES beta_tasks(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'not_started', ui_element_code TEXT, severity TEXT, reproduction_steps TEXT, expected_result TEXT, actual_result TEXT, notes TEXT, saved_at TEXT, submitted_at TEXT, UNIQUE(user_id, task_id));
CREATE TABLE IF NOT EXISTS beta_sessions_time (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES beta_users(id) ON DELETE CASCADE, started_at TEXT NOT NULL, last_activity_at TEXT NOT NULL, ended_at TEXT, active_seconds INTEGER NOT NULL DEFAULT 0, inactive_seconds INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS beta_agreements (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES beta_users(id) ON DELETE CASCADE, stage_key TEXT NOT NULL, decision TEXT NOT NULL CHECK (decision IN ('agreed','declined')), decline_reason TEXT, agreed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, stage_key));
CREATE INDEX IF NOT EXISTS beta_responses_user_idx ON beta_responses(user_id);
CREATE INDEX IF NOT EXISTS beta_sessions_user_idx ON beta_sessions_time(user_id);
CREATE INDEX IF NOT EXISTS beta_agreements_stage_idx ON beta_agreements(stage_key);
